export enum StatePositionSource {
	ADSB = 0,
	ASTERIX = 1,
	MLAT = 2,
	FLARM = 3,
};

export enum StateCategory {
  //No information at all
	NoInformation = 0,
  //No ADS-B Emitter Category Information
	NoADSB = 1,
  //Light (< 15500 lbs)
	Light = 2,
  //Small (15500 to 75000 lbs)
	Small = 3,
  //Large (75000 to 300000 lbs)
	Large = 4,
  //High Vortex Large (aircraft such as B-757)
	HighVortexLarge = 5,
  //Heavy (> 300000 lbs)
	Heavy = 6,
  //High Performance (> 5g acceleration and 400 kts)
	HighPerformance = 7,
  //Rotorcraft
	Rotorcraft = 8,
  //Glider / sailplane
	Glider = 9,
  //Lighter-than-air
	LighterThanAir = 10,
  //Parachutist / Skydiver
	Skydiver = 11,
  //Ultralight / hang-glider / paraglider
	Ultralight = 12,
  //Reserved
	Reserved = 13,
  //Unmanned Aerial Vehicle
	UAV = 14,
  //Space / Trans-atmospheric vehicle
	Space = 15,
  //Surface Vehicle – Emergency Vehicle
	SurfaceEmergency = 16,
  //Surface Vehicle – Service Vehicle
	SurfaceService = 17,
  //Point Obstacle (includes tethered balloons)
	PointObstacle = 18,
  //Cluster Obstacle
	ClusterObstacle = 19,
  //Line Obstacle
	Line = 20,
};

